//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

#[derive(Default)]
struct BoardState {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    // A single lock protects both player scores and the running total so
    // read-modify-write updates stay atomic, total always matches player
    // scores, and multi-player transfers cannot deadlock.
    state: Arc<Mutex<BoardState>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.state.lock().unwrap();
        if let Some(previous) = state.players.insert(id, score) {
            state.total -= previous;
        }
        state.total += score;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let found = {
            let mut state = self.state.lock().unwrap();
            if let Some(score) = state.players.get_mut(&id) {
                *score += points;
                state.total += points;
                true
            } else {
                false
            }
        };
        if !found {
            panic!("unknown player: {id}");
        }
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let missing = {
            let mut state = self.state.lock().unwrap();
            if !state.players.contains_key(&from) {
                Some(from)
            } else if !state.players.contains_key(&to) {
                Some(to)
            } else {
                if from != to {
                    *state.players.get_mut(&from).unwrap() -= points;
                    *state.players.get_mut(&to).unwrap() += points;
                }
                None
            }
        };
        if let Some(id) = missing {
            panic!("unknown player: {id}");
        }
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        let score = self.state.lock().unwrap().players.get(&id).copied();
        score.unwrap_or_else(|| panic!("unknown player: {id}"))
    }

    pub fn total(&self) -> i64 {
        self.state.lock().unwrap().total
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{mpsc, Barrier};
    use std::thread;
    use std::time::Duration;

    fn run_with_timeout<F>(timeout: Duration, f: F)
    where
        F: FnOnce() + Send + 'static,
    {
        let (tx, rx) = mpsc::channel();
        thread::spawn(move || {
            f();
            let _ = tx.send(());
        });
        rx.recv_timeout(timeout)
            .expect("operation timed out (likely deadlock)");
    }

    #[test]
    fn concurrent_award_does_not_lose_updates() {
        let board = Board::new();
        board.join(1, 0);
        board.join(2, 0);

        let threads = 8;
        let iters = 5_000;
        let barrier = Arc::new(Barrier::new(threads));

        let mut handles = Vec::with_capacity(threads);
        for t in 0..threads {
            let b = board.clone();
            let bar = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                bar.wait();
                for _ in 0..iters {
                    let target = if t % 2 == 0 { 1 } else { 2 };
                    b.award(target, 1);
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }

        let per_player = (threads / 2) as i64 * iters as i64;
        assert_eq!(board.score(1), per_player);
        assert_eq!(board.score(2), per_player);
        assert_eq!(board.total(), per_player * 2);
    }

